/*
 * HTML 'Agent 도구 선택 도우미' 카드 썸네일 올리기 (브라우저 콘솔용)
 *   HubContents 의 그 항목에 첨부 파일 thumb.png 를 넣습니다. 이미 있으면 바꿉니다.
 *   그림 원본: samples/demo/thumbs/agent-tool-picker-thumb.png (도구의 추천 결과 화면)
 *   ※ 썸네일을 읽는 새 Hub 코드가 배포된 뒤에 실행하세요. 예전 코드는 thumb.png 를 HTML 파일로 잘못 집습니다.
 *   지우려면 Console 에 hubThumbRemove() 입력.
 */
(() => {
  const TITLE = 'Agent 도구 선택 도우미';
  const B64 = '';
  const web = _spPageContextInfo.webAbsoluteUrl, J = { Accept: 'application/json;odata=verbose' };
  const L = web + "/_api/web/lists/getbytitle('HubContents')";
  const digest = async () => (await (await fetch(web + '/_api/contextinfo', { method: 'POST', headers: J })).json()).d.GetContextWebInformation.FormDigestValue;
  const find = async () => {
    const rows = (await (await fetch(L + "/items?$select=Id,Title,AttachmentFiles/FileName&$expand=AttachmentFiles&$filter=Kind eq 'HTML'&$top=5000", { headers: J })).json()).d.results;
    const r = rows.filter(x => (x.Title || '').trim() === TITLE)[0];
    if (!r) { throw new Error("'" + TITLE + "' HTML을 찾지 못했어요"); }
    return { id: r.Id, files: ((r.AttachmentFiles && r.AttachmentFiles.results) || []).map(f => f.FileName) };
  };
  const del = async (D, id, name) => fetch(L + '/items(' + id + ")/AttachmentFiles/getByFileName('" + encodeURIComponent(name) + "')", { method: 'POST', headers: { ...J, 'X-RequestDigest': D, 'X-HTTP-Method': 'DELETE', 'IF-MATCH': '*' } });
  (async () => {
    const it = await find(), D = await digest();
    for (const n of it.files.filter(n => /^thumb\./i.test(n))) { await del(D, it.id, n); }
    const bytes = Uint8Array.from(atob(B64), c => c.charCodeAt(0));
    const r = await fetch(L + '/items(' + it.id + ")/AttachmentFiles/add(FileName='thumb.png')", { method: 'POST', headers: { ...J, 'X-RequestDigest': D }, body: bytes });
    console.log(r.ok ? '✅ 썸네일(thumb.png)을 올렸어요. Hub를 새로 고쳐 HTML 카드를 확인해 보세요.' : '❌ 올리지 못했어요 ' + r.status + ' ' + (await r.text()).slice(0, 200));
  })().catch(e => console.error('중간에 멈췄어요:', e.message));
  window.hubThumbRemove = async () => {
    const it = await find(), D = await digest();
    for (const n of it.files.filter(n => /^thumb\./i.test(n))) { await del(D, it.id, n); }
    console.log('썸네일을 지웠어요.');
  };
})();